function libraryMatch(asset,chosen,term){return (chosen==='All'||asset.category===chosen)&&(chosen!=='Studio Artwork'||xelaGroup==='All'||asset.group===xelaGroup)&&[asset.name,asset.group||'',asset.filename||''].join(' ').toLowerCase().includes(term.toLowerCase());}
function renderLibrary(){let items=SVG_LIBRARY.filter(a=>libraryMatch(a,category,$('librarySearch').value));$('libraryGrid').replaceChildren(...items.slice(0,18).map(a=>assetCard(a,false)));$('libraryCount').textContent='('+SVG_LIBRARY.length+')';renderChips($('categories'),category,v=>{category=v;renderLibrary();});}
