 if(active==='layers'&&qs('.sidebar').hidden)active=qs('.inspector').hidden?null:qs('[data-tab].active')?.dataset.tab;
 if(['animate','colors','canvas'].includes(active)&&qs('.inspector').hidden)active=qs('.sidebar').hidden?null:'layers';
 if(!library&&active)foregroundTool=active;
 qsa('[data-nav]').forEach(button=>{const yes=button.dataset.nav===active;button.classList.toggle('active',yes);button.setAttribute('aria-pressed',String(yes));button.setAttribute('aria-expanded',String(button.dataset.nav==='library'?library:button.dataset.nav==='layers'?!library&&!qs('.sidebar').hidden:yes));});
