 const host=$('layersList'),children=new Map(),selected=new Set(state.selected);
 if(layerState!==state.objects){layerCache.clear();layerState=state.objects;}
 for(const item of Object.values(state.objects)){if(!children.has(item.parent))children.set(item.parent,[]);children.get(item.parent).push(item);}
